            ["gar.s.tablet.t"] = "Your whole shop. One tablet.",
            ["gar.s.tablet.d"] = "Big touch tiles for the counter and the bays, and a six-digit PIN for each person. Owner, advisor, technician, parts: each sees what their job needs.",
            ["gar.s.tablet.alt"] = "MapleGarage home screen with large tiles for appointments, check-in, quotes, my jobs and parts",
            ["gar.ai.title"] = "The phone at 9 p.m. gets answered.",
            ["gar.ai.d"] = "The MapleGarage assistant answers your web chat, text messages and phone line. It takes the name, the car and the problem, opens a repair request for your advisor, and texts the owner a link to send photos.",
            ["gar.ai.r1"] = "It never guesses a diagnosis or a price. That stays with you.",
            ["gar.ai.r2"] = "If the car sounds unsafe, it tells the owner not to drive it and asks if they need a tow.",
            ["gar.ai.r3"] = "It answers in the customer's language and checks the details with them before saving anything.",
            ["gar.more.title"] = "Also in the box.",
            ["gar.more.kiosk.t"] = "“Where's my car?”",
            ["gar.more.kiosk.d"] = "Customers type their phone number at the counter screen and see where their car is.",
            ["gar.more.tv.t"] = "Waiting-room TV",
            ["gar.more.tv.d"] = "Cars in the shop, ready for pickup and today's bookings. First names only, never a full plate.",
            ["gar.more.follow.t"] = "Follow-ups",
            ["gar.more.follow.d"] = "Call-backs after pickup and service-due reminders, worked out from the car's own mileage.",
            ["gar.more.card.t"] = "Card terminal",
            ["gar.more.card.d"] = "Take card on a PAX terminal, or record payments from the machine you already have.",
            ["gar.end.title"] = "Run the shop, not the paperwork.",
