            ["prod.agent.name"] = "AI Voice Agent",
            ["prod.agent.for"] = "Answers your phone. Sold on its own.",
            ["hp.ai.more"] = "Meet the AI voice agent, sold on its own",
            ["ag.meta.title"] = "AI Voice Agent: every call answered, day or night | MapleKiosk",
            ["ag.meta.desc"] = "An AI voice agent for your business phone. It books appointments, takes pickup orders and reservations, and answers questions about hours, prices and parking, in whatever language your customer speaks. Sold on its own.",
            ["ag.product"] = "MapleKiosk AI Voice Agent",
            ["ag.hero.title"] = "Every call answered.",
            ["ag.hero.sub"] = "The AI voice agent picks up when your hands are busy, day or night, in a natural, friendly voice. Your customer speaks their language and it answers in the same one. It books appointments, takes pickup orders and answers the questions you hear every day.",
            ["ag.hero.watch"] = "Watch the film",
            ["ag.hero.alone"] = "Sold on its own: you don't need any other MapleKiosk product. Already run one of our systems? The agent is built in.",
            ["ag.watch"] = "Watch this part",
            ["ag.why.title"] = "Your hands are busy. The phone rings anyway.",
            ["ag.why.d"] = "You're mid-manicure, pulling a shot or running plates in the dinner rush. The call goes to voicemail, and that customer calls someone else.",
            ["ag.why.alt"] = "A phone's notifications: four missed calls, each sent to voicemail.",
            ["ag.does.title"] = "What it does on the call",
            ["ag.does.sub"] = "Every picture is from the film. Click one to watch that part.",
            ["ag.s.book.t"] = "Books the appointment",
            ["ag.s.book.d"] = "For salons, it books, reschedules and confirms appointments right into your calendar, then texts the customer.",
            ["ag.s.book.alt"] = "A call to Maple Nails: the caller asks for a gel manicure on Saturday around two, and the agent books 2 PM with Linda and sends a text.",
            ["ag.s.order.t"] = "Takes the order",
            ["ag.s.order.d"] = "For cafés and restaurants, it takes pickup orders and reservations and answers questions about your menu.",
            ["ag.s.order.alt"] = "A call to Café Maple: two lattes and a croissant for pickup become order #1042, ready in ten minutes.",
            ["ag.s.questions.t"] = "Answers the everyday questions",
            ["ag.s.questions.d"] = "Your hours, prices, location and parking: the questions any business hears all day.",
            ["ag.s.questions.alt"] = "Questions and answers: hours, price, address and parking.",
            ["ag.s.team.t"] = "Knows when to pass the phone",
            ["ag.s.team.d"] = "It answers several calls at once and replies in the caller's own language, whatever it is. It texts confirmations and hands off to your team when a human is needed.",
            ["ag.s.team.alt"] = "Four points: several calls at once, English and French, text confirmations, hands off to your team.",
            ["ag.own.title"] = "Buy it on its own.",
            ["ag.own.d"] = "The agent answers your phone whatever system runs your counter. It suits salons, cafés, restaurants and garages, and any business that misses calls.",
            ["ag.own.r1"] = "You don't need a MapleKiosk till, tablet or kiosk.",
            ["ag.own.r2"] = "Already on MapleCoffee, MapleSPA, MaplePOS or MapleGarage? The agent is built in, so bookings and orders go straight into the system you run.",
            ["ag.own.r3"] = "Start with the agent today. Add the rest of a system later if you want it.",
            ["ag.in.title"] = "Already inside every MapleKiosk system",
            ["ag.in.sub"] = "If you run one of our systems, the agent works inside it.",
            ["ag.in.coffee"] = "Takes pickup orders by phone and sends them to the till.",
            ["ag.in.nails"] = "Books into the salon calendar with the right technician.",
            ["ag.in.resto"] = "Takes reservations and pickup orders.",
            ["ag.in.garage"] = "Takes the name, the car and the problem, and opens a repair request.",
            ["ag.end.title"] = "Never miss a call again.",

