            // Restaurant page (MaplePOS)
            ["rp.meta.title"] = "MaplePOS — restaurant POS for sit-down dining rooms | MapleKiosk",
            ["rp.meta.desc"] = "A floor board that tells your team what's next, table QR ordering in the guest's language, a kitchen display, an AI that books tables by phone and text, and the bill and tips in seconds. Made in Québec.",
            ["rp.hero.title"] = "Run the floor, not the chaos.",
            ["rp.hero.sub"] = "MaplePOS is the point of sale for sit-down restaurants. It tells your team what to do next, sends every order to the kitchen, books tables while you sleep and closes the bill in seconds.",
            ["rp.hero.watch"] = "Watch the film",
            ["rp.hero.note"] = "Every screen in these films is in the app today.",
            ["rp.hero.alt"] = "The MaplePOS floor board: every table with its phase, guests and time, and a Next up list",
            ["rp.watch"] = "Watch",
            ["rp.lang"] = "Films in",
            ["rp.night.title"] = "One night at the bistro",
            ["rp.night.sub"] = "Follow a service from the first booking to the last tip. Each step is a one-minute film.",
            ["rp.s.book.t"] = "A full book, never a double booking",
            ["rp.s.book.d"] = "Reservations land on a day book — tables across, time down — so a table can't be sold twice. Guests who arrive go to the lobby, and walk-ins get a quoted wait and a table in a couple of taps.",
            ["rp.s.book.alt"] = "The day book: tables across, times down, bookings in each slot",
            ["rp.s.phone.t"] = "Book tables while you sleep",
            ["rp.s.phone.d"] = "The AI assistant answers the phone and books into tables that are really free. Guests can also text to book — in their own language — or book online. A call it can't handle comes back to your staff as a callback.",
            ["rp.s.phone.alt"] = "The AI assistant on a call beside the day book",
            ["rp.s.floor.t"] = "Always know your next move",
            ["rp.s.floor.d"] = "The floor board shows every table — free, waiting on us, dining, leaving — with its guests and time. “Next up” tells the team what matters now: run the plates, answer a guest, take the order, offer the bill.",
            ["rp.s.floor.alt"] = "The floor board with the Next up list",
            ["rp.s.qr.t"] = "Every table orders in its own language",
            ["rp.s.qr.d"] = "Guests scan the table QR and order from their phone in English, French, Spanish or Vietnamese. Nothing goes to the kitchen until they press Send — and when they ask for the bill, the floor sees it.",
            ["rp.s.qr.alt"] = "The table QR menu on a guest's phone",
            ["rp.s.kitchen.t"] = "Kitchen and floor in sync",
            ["rp.s.kitchen.d"] = "Orders arrive on the kitchen display, round by round. Cooks mark each line ready, the floor sees the plates are up, and station tickets print where they're needed. No shouting across the room.",
            ["rp.s.kitchen.alt"] = "The kitchen display with rounds and Start All",
            ["rp.s.bill.t"] = "The bill in seconds, tips without the awkward",
            ["rp.s.bill.d"] = "The guest picks a tip on their own screen, then taps or inserts their card. Part payments, cash discounts, gift cards, and manager-approved discounts with a PIN are all built in.",
            ["rp.s.bill.alt"] = "The tip screen: No tip, 15%, 18%, 20% or Custom",
