            ["hp.nails.trade"] = "Ongles et spa",
            ["hp.nails.line"] = "Samedi, les clientes sans rendez-vous arrivent : quatre techniciennes, un tour juste. Pourboires et commissions se calculent seuls à la fermeture.",
            ["hp.nails.more"] = "Voir MapleSPA",
            ["hp.garage.trade"] = "Garage",
            ["hp.garage.line"] = "Chaque auto est un travail. Le mécanicien appuie sur Démarrer, prend les pièces sur l'étagère, appuie sur Terminé.",
            ["hp.garage.page"] = "Page complète bientôt",
            ["hp.resto.trade"] = "Restaurant",
            ["hp.resto.line"] = "Un plan de salle qui dit à l'équipe quoi faire, la commande à table dans la langue du client, les bons directement en cuisine, et une IA qui réserve par téléphone.",
            ["hp.resto.more"] = "Voir MaplePOS",
            ["hp.ai.title"] = "Une IA qui fait un vrai travail, dans la langue de votre client.",
            ["hp.ai.sub"] = "Pas de mots à la mode. Deux choses qu'elle fait déjà.",
            ["hp.ai.coffee.text"] = "Un client commande à voix haute à la borne vocale MapleCoffee. La commande s'affiche, prête à payer.",
            ["hp.ai.nails.text"] = "La réceptionniste MapleSPA répond au téléphone du salon, vérifie l'agenda et confirme le rendez-vous — même à 21 h.",
            ["hp.co.title"] = "Une entreprise d'ici, pas un centre d'appels.",
            ["hp.co.text"] = "Kiosque Érable inc. conçoit MapleKiosk à Longueuil, au Québec. Écrivez-nous en français, en anglais, en vietnamien ou en russe : ce sont les gens qui le construisent qui vous répondent.",
            ["hp.co.place"] = "Longueuil (Québec)",
            ["hp.co.langs"] = "Français · English · Tiếng Việt · Русский",
            ["hp.co.email"] = "Écrivez-nous",
            ["hp.co.videos"] = "Toutes nos vidéos",
            ["hp.end.title"] = "Choisissez votre métier, ou parlez-nous tout simplement.",
            ["hp.end.or"] = "ou écrivez à",

            // Garage page (/garage)
            ["hp.garage.more"] = "Voir MapleGarage",
            ["gar.meta.title"] = "MapleGarage — Logiciel pour garages indépendants | MapleKiosk",
            ["gar.meta.desc"] = "Rendez-vous, réception avec photos et signature, soumissions travail par travail, tableau de l'atelier, travaux des mécaniciens, pièces et facture — sur une seule tablette. Conçu pour les garages indépendants.",
            ["gar.hero.title"] = "Du coup de fil à la remise des clés.",
            ["gar.hero.sub"] = "MapleGarage fait rouler un garage indépendant sur une seule tablette : le rendez-vous, la réception du véhicule, la soumission que le client accepte ou refuse, le tableau des travaux, les pièces et la facture.",
            ["gar.hero.watch"] = "Voir la visite",
            ["gar.hero.note"] = "Chaque image de cette page est un vrai écran de MapleGarage. L'application fonctionne en français, en anglais et en espagnol.",
            ["gar.watch"] = "Voir ce passage",
            ["gar.day.title"] = "Une auto arrive.",
            ["gar.day.sub"] = "Suivez un bon de travail du rendez-vous jusqu'aux clés. Cliquez sur un écran pour voir ce passage de la visite.",
            ["gar.s.book.t"] = "Des rendez-vous bien dosés.",
            ["gar.s.book.d"] = "Un calendrier avec un nombre d'autos par jour et de baies que vous fixez, pour ne jamais promettre plus que ce que vous pouvez réparer. Le client reçoit un texto quand le rendez-vous est pris ou déplacé.",
            ["gar.s.check-in.t"] = "Une réception avec preuves.",
            ["gar.s.check-in.d"] = "Odomètre, essence, numéro de clé, les problèmes signalés, une inspection rapide avec photos et la signature du client. Il reçoit le reçu de dépôt sur son téléphone, qui précise qu'aucun travail ne commence sans son accord sur une soumission.",
            ["gar.s.quote.t"] = "Des soumissions, travail par travail.",
            ["gar.s.quote.d"] = "Ce que vous trouvez devient des travaux avec pièces, main-d'œuvre et taxes, marqués Sécurité ou Bientôt. Le client reçoit la soumission par texto et vous donne un oui ou un non pour chaque travail : les freins n'attendent jamais l'équilibrage.",
            ["gar.s.board.t"] = "Toutes les autos, d'un coup d'œil.",
            ["gar.s.board.d"] = "Arrivée, en attente du client, en réparation, en attente de pièces, prête. Une auto qui dépasse l'heure promise est signalée en retard.",
            ["gar.s.my-jobs.t"] = "Mes travaux.",
            ["gar.s.my-jobs.d"] = "Chaque mécanicien voit ses travaux sur toutes les autos. Démarrer, pause, terminé — et la pièce sort de l'étagère d'un seul geste.",
            ["gar.s.parts.t"] = "Les pièces, sans la paperasse.",
            ["gar.s.parts.d"] = "Voyez ce qui manque, mettez-le sur une commande et recevez-le sur cette commande. Une commande spéciale reste liée à l'auto concernée.",
            ["gar.s.bill.t"] = "La facture suit la soumission.",
            ["gar.s.bill.d"] = "La facture est faite à partir des travaux acceptés, au prix soumis. Encaissez l'argent comptant d'un geste par billet, ou la carte sur votre terminal.",
            ["gar.s.car-story.t"] = "L'histoire de chaque auto.",
            ["gar.s.car-story.d"] = "Chaque visite, l'odomètre à l'arrivée et au départ, les travaux refusés et le prochain entretien, enregistrés sur l'auto. Tout est là quand elle revient.",
            ["gar.s.tablet.t"] = "Tout le garage. Une seule tablette.",
            ["gar.s.tablet.d"] = "De grandes tuiles tactiles pour le comptoir et les baies, et un NIP à six chiffres par personne. Propriétaire, conseiller, mécanicien, pièces : chacun voit ce dont son travail a besoin.",
            ["gar.ai.title"] = "L'appel de 21 h trouve une réponse.",
            ["gar.ai.d"] = "L'assistant MapleGarage répond à votre clavardage, à vos textos et à votre ligne téléphonique. Il note le nom, l'auto et le problème, ouvre une demande de réparation pour votre conseiller et texte au client un lien pour envoyer des photos.",
            ["gar.ai.r1"] = "Il ne devine jamais un diagnostic ni un prix. Ça reste votre affaire.",
            ["gar.ai.r2"] = "Si l'auto semble dangereuse, il dit au client de ne pas la conduire et demande s'il faut une remorqueuse.",
            ["gar.ai.r3"] = "Il répond dans la langue du client et vérifie les détails avec lui avant d'enregistrer quoi que ce soit.",
            ["gar.more.title"] = "Et aussi.",
            ["gar.more.kiosk.t"] = "« Où en est mon auto? »",
            ["gar.more.kiosk.d"] = "Le client tape son numéro de téléphone à l'écran du comptoir et voit où en est son auto.",
            ["gar.more.tv.t"] = "Télé de la salle d'attente",
            ["gar.more.tv.d"] = "Autos à l'atelier, prêtes à partir et rendez-vous du jour. Le prénom seulement, jamais la plaque complète.",
            ["gar.more.follow.t"] = "Suivis",
            ["gar.more.follow.d"] = "Rappels après la remise et avis d'entretien, calculés à partir du kilométrage réel de l'auto.",
            ["gar.more.card.t"] = "Terminal de paiement",
            ["gar.more.card.d"] = "Encaissez par carte sur un terminal PAX, ou inscrivez les paiements faits sur le terminal que vous avez déjà.",
            ["gar.end.title"] = "Gérez le garage, pas la paperasse.",
