            ["hp.ai.more"] = "Découvrez l'agent vocal IA, vendu seul",
            ["ag.meta.title"] = "Agent vocal IA : chaque appel répondu, jour et nuit | MapleKiosk",
            ["ag.meta.desc"] = "Un agent vocal IA pour le téléphone de votre commerce. Il prend les rendez-vous, les commandes pour emporter et les réservations, et répond sur les heures, les prix et le stationnement, dans la langue de votre client. Vendu seul.",
            ["ag.product"] = "Agent vocal IA MapleKiosk",
            ["ag.hero.title"] = "Chaque appel répondu.",
            ["ag.hero.sub"] = "L'agent vocal IA décroche quand vous avez les mains pleines, jour et nuit, d'une voix naturelle et chaleureuse. Votre client parle sa langue, l'agent lui répond dans la même. Il prend les rendez-vous et les commandes pour emporter, et répond aux questions de tous les jours.",
            ["ag.hero.watch"] = "Voir le film (en anglais)",
            ["ag.hero.alone"] = "Vendu seul : aucun autre produit MapleKiosk n'est nécessaire. Vous utilisez déjà un de nos systèmes ? L'agent y est intégré.",
            ["ag.watch"] = "Voir ce passage",
            ["ag.why.title"] = "Vous avez les mains pleines. Le téléphone sonne quand même.",
            ["ag.why.d"] = "En pleine manucure, en train de tirer un espresso ou de servir en plein rush du souper : l'appel tombe sur la boîte vocale, et ce client appelle ailleurs.",
            ["ag.why.alt"] = "Les notifications d'un téléphone : quatre appels manqués, tous envoyés à la boîte vocale.",
            ["ag.does.title"] = "Ce qu'il fait au téléphone",
            ["ag.does.sub"] = "Chaque image vient du film. Cliquez pour voir ce passage.",
            ["ag.s.book.t"] = "Il prend le rendez-vous",
            ["ag.s.book.d"] = "Pour les salons, il prend, déplace et confirme les rendez-vous directement dans votre agenda, puis texte le client.",
            ["ag.s.book.alt"] = "Un appel à Maple Nails : la cliente demande une manucure gel samedi vers 14 h ; l'agent réserve 14 h avec Linda et envoie un texto.",
            ["ag.s.order.t"] = "Il prend la commande",
            ["ag.s.order.d"] = "Pour les cafés et les restaurants, il prend les commandes pour emporter et les réservations, et répond aux questions sur votre menu.",
            ["ag.s.order.alt"] = "Un appel au Café Maple : deux lattés et un croissant pour emporter deviennent la commande no 1042, prête dans dix minutes.",
            ["ag.s.questions.t"] = "Il répond aux questions de tous les jours",
            ["ag.s.questions.d"] = "Vos heures, vos prix, votre adresse et le stationnement : les questions que toute entreprise entend à longueur de journée.",
            ["ag.s.questions.alt"] = "Questions et réponses : heures, prix, adresse et stationnement.",
            ["ag.s.team.t"] = "Il sait quand passer l'appel",
            ["ag.s.team.d"] = "Il répond à plusieurs appels à la fois, dans la langue de l'appelant, quelle qu'elle soit. Il texte les confirmations et transfère à votre équipe quand il faut un humain.",
            ["ag.s.team.alt"] = "Quatre points : plusieurs appels à la fois, français et anglais, confirmations par texto, transfert à votre équipe.",
            ["ag.own.title"] = "Achetez-le seul.",
            ["ag.own.d"] = "L'agent répond à votre téléphone, peu importe le système derrière votre comptoir. Il convient aux salons, cafés, restaurants et garages, et à toute entreprise qui manque des appels.",
            ["ag.own.r1"] = "Aucune caisse, tablette ni borne MapleKiosk n'est nécessaire.",
            ["ag.own.r2"] = "Vous utilisez déjà MapleCoffee, MapleSPA, MaplePOS ou MapleGarage ? L'agent y est intégré : les rendez-vous et les commandes entrent directement dans votre système.",
            ["ag.own.r3"] = "Commencez par l'agent aujourd'hui. Ajoutez le reste d'un système plus tard, si vous le voulez.",
            ["ag.in.title"] = "Déjà dans chaque système MapleKiosk",
            ["ag.in.sub"] = "Si vous utilisez un de nos systèmes, l'agent fonctionne à l'intérieur.",
            ["ag.in.coffee"] = "Prend les commandes pour emporter au téléphone et les envoie à la caisse.",
