            // Restaurant page (MaplePOS)
            ["rp.meta.title"] = "MaplePOS — caisse pour restaurants avec service aux tables | MapleKiosk",
            ["rp.meta.desc"] = "Un plan de salle qui dit à l'équipe quoi faire, la commande par QR à table dans la langue du client, un écran de cuisine, une IA qui réserve par téléphone et texto, et l'addition et le pourboire en quelques secondes. Fait au Québec.",
            ["rp.hero.title"] = "Menez la salle, pas le chaos.",
            ["rp.hero.sub"] = "MaplePOS est la caisse des restaurants avec service aux tables. Elle dit à votre équipe quoi faire ensuite, envoie chaque commande en cuisine, réserve des tables pendant que vous dormez et règle l'addition en quelques secondes.",
            ["rp.hero.watch"] = "Voir le film",
            ["rp.hero.note"] = "Chaque écran de ces films existe déjà dans l'application.",
            ["rp.hero.alt"] = "Le plan de salle MaplePOS : chaque table avec sa phase, ses clients et son temps, et la liste « À faire ensuite »",
            ["rp.watch"] = "Voir",
            ["rp.lang"] = "Films en",
            ["rp.night.title"] = "Une soirée au bistro",
            ["rp.night.sub"] = "Suivez un service de la première réservation au dernier pourboire. Chaque étape est un film d'une minute.",
            ["rp.s.book.t"] = "Un carnet plein, jamais de double réservation",
            ["rp.s.book.d"] = "Les réservations s'affichent dans un carnet du jour — les tables en colonnes, l'heure en lignes — pour qu'une table ne soit jamais vendue deux fois. Les clients arrivés passent au hall, et les clients sans réservation reçoivent une attente estimée et une table en quelques touches.",
            ["rp.s.book.alt"] = "Le carnet du jour : les tables en colonnes, l'heure en lignes",
            ["rp.s.phone.t"] = "Réservez des tables pendant que vous dormez",
            ["rp.s.phone.d"] = "L'assistant IA répond au téléphone et réserve sur des tables réellement libres. Les clients peuvent aussi réserver par texto — dans leur langue — ou en ligne. Un appel qu'il ne peut pas traiter revient à votre équipe comme rappel.",
            ["rp.s.phone.alt"] = "L'assistant IA en appel à côté du carnet du jour",
            ["rp.s.floor.t"] = "Sachez toujours quoi faire ensuite",
            ["rp.s.floor.d"] = "Le plan de salle montre chaque table — libre, en attente de nous, en repas, sur le départ — avec ses clients et son temps. « À faire ensuite » dit à l'équipe ce qui compte : servir les assiettes, répondre à un client, prendre la commande, proposer l'addition.",
            ["rp.s.floor.alt"] = "Le plan de salle avec la liste « À faire ensuite »",
            ["rp.s.qr.t"] = "Chaque table commande dans sa langue",
            ["rp.s.qr.d"] = "Les clients scannent le QR de la table et commandent sur leur téléphone en anglais, français, espagnol ou vietnamien. Rien ne part en cuisine avant qu'ils appuient sur Envoyer — et quand ils demandent l'addition, la salle le voit.",
            ["rp.s.qr.alt"] = "Le menu QR de la table sur le téléphone d'un client",
            ["rp.s.kitchen.t"] = "Cuisine et salle synchronisées",
            ["rp.s.kitchen.d"] = "Les commandes arrivent sur l'écran de cuisine, service par service. Les cuisiniers marquent chaque ligne prête, la salle voit que les assiettes sont sorties, et les bons de poste s'impriment là où il faut. Plus besoin de crier.",
            ["rp.s.kitchen.alt"] = "L'écran de cuisine avec les services et « Tout lancer »",
            ["rp.s.bill.t"] = "L'addition en secondes, le pourboire sans malaise",
            ["rp.s.bill.d"] = "Le client choisit son pourboire sur son propre écran, puis tape ou insère sa carte. Paiements partiels, escompte au comptant, cartes-cadeaux et rabais approuvés par un gérant avec NIP sont intégrés.",
            ["rp.s.bill.alt"] = "L'écran de pourboire : aucun, 15 %, 18 %, 20 % ou autre",
            ["rp.s.tips.t"] = "Pourboires équitables, paie réglée",
            ["rp.s.tips.d"] = "Le personnel pointe avec un NIP. Les pourboires se partagent selon votre règle — mis en commun, gardés par le serveur, ou une part gardée — et la paie avec heures supplémentaires s'exporte en CSV.",
            ["rp.s.tips.alt"] = "Le partage des pourboires selon la règle de la maison",
            ["rp.s.regulars.t"] = "Faites des nouveaux clients des habitués",
            ["rp.s.regulars.d"] = "Les clients s'inscrivent aux points directement sur l'écran de paiement. Leur fiche retient anniversaires et allergies, et les campagnes courriel ramènent les anniversaires et ceux qu'on n'a pas vus depuis un moment.",
            ["rp.s.regulars.alt"] = "L'inscription aux points sur l'écran du client",
            ["rp.s.menu.t"] = "Changez le menu une seule fois",
            ["rp.s.menu.d"] = "Modifiez un plat une seule fois, avec la raison du changement de prix gardée dans l'historique. Le menu QR, la tablette du serveur et l'écran mural affichent le même prix.",
            ["rp.s.menu.alt"] = "Le même prix sur le menu QR, la tablette et l'écran mural",
            ["rp.end.title"] = "Prêt à mener la salle, pas le chaos?",
        },

