            ["cof.day.sub"] = "Bảy việc hằng ngày ở quán cà phê và cách MapleCoffee lo từng việc. Mỗi việc có một phim dài một phút.",
            ["cof.s.rush.t"] = "Giờ cao điểm sáng: đúng món, đúng tên",
            ["cof.s.rush.d"] = "Mỗi order tới quầy pha chế có ghi rõ món, yêu cầu riêng và tên khách. Nhân viên pha chế làm theo thứ tự và gọi đúng tên, kể cả khi khách xếp hàng ra tới cửa.",
            ["cof.s.rush.alt"] = "Anh barista Alvin trước hàng khách buổi sáng",
            ["cof.s.kiosk.t"] = "Thêm một quầy tính tiền không bao giờ nghỉ",
            ["cof.s.kiosk.d"] = "Khách gọi món ở kiosk hoặc đặt trước trên điện thoại. Khách bấm Order Now, chọn món và tự kiểm tra order, rồi order đi thẳng vào quầy pha chế. Nhân viên cứ pha nước trong khi hàng vẫn chạy đều.",
            ["cof.s.kiosk.alt"] = "Kiosk gọi món với nút Order Now",
            ["cof.s.voice.t"] = "Khách chỉ cần nói món, bằng tiếng của mình",
            ["cof.s.voice.d"] = "Ở kiosk giọng nói, khách chỉ cần nói muốn uống gì, bằng tiếng Anh, tiếng Pháp hay tiếng của mình. Order hiện lên màn hình trong lúc khách nói, rồi khách xác nhận.",
            ["cof.s.voice.alt"] = "Khách gọi món bằng tiếng Pháp ở kiosk giọng nói",
            ["cof.s.checkout.t"] = "Tính tiền nhanh, tip không ngại ngùng",
            ["cof.s.checkout.d"] = "Khách chọn tip trên màn hình của mình rồi quẹt hoặc cắm thẻ. Không ai phải xoay màn hình rồi đứng chờ, và hàng vẫn chạy đều.",
            ["cof.s.checkout.alt"] = "Tiêu đề: tính tiền gọn hơn",
            ["cof.s.loyalty.t"] = "Biến khách mới thành khách quen",
            ["cof.s.loyalty.d"] = "Khách tích điểm và nhận ưu đãi, như giảm $2, được áp dụng ngay tại quầy. Thẻ quà tặng bán và dùng trên cùng một màn hình.",
            ["cof.s.loyalty.alt"] = "Màn hình quầy áp dụng ưu đãi chào mừng giảm $2",
            ["cof.s.tips.t"] = "Chia tip công bằng, tính lương vài phút",
            ["cof.s.tips.d"] = "Chọn cách chia tip: gom chung cho mọi người trong ca, người phục vụ giữ, hoặc người phục vụ giữ một phần và phần còn lại gom chung. MapleCoffee tự tính trên mỗi order, nên tính lương chỉ mất vài phút.",
            ["cof.s.tips.alt"] = "Cài đặt tip: gom chung, người phục vụ giữ, hoặc giữ một phần",
            ["cof.s.tips.howto"] = "Cách cài đặt chia tip",
            ["cof.s.menu.t"] = "Đổi giá một lần, đúng ở mọi nơi",
            ["cof.s.menu.d"] = "Đổi giá hay đổi món chỉ một lần. Quầy, kiosk và đặt món online đều cập nhật liền, không ai bị tính giá cũ.",
            ["cof.s.menu.alt"] = "Tiêu đề: đổi một lần",
            ["cof.end.title"] = "Thử MapleCoffee ngay tại quán của anh chị.",
            ["cof.cta.trial"] = "Chạy thử",

