            ["hp.h1"] = "Bạn đang kinh doanh gì?",
            ["hp.sub"] = "MapleKiosk là phần mềm bán hàng và lễ tân, làm riêng cho từng ngành. Chọn ngành của bạn và xem video một phút về cách nó vận hành một ngày làm việc.",
            ["hp.watch"] = "Xem",
            ["hp.soon"] = "Sắp có",
