            ["hp.coffee.trade"] = "Quán cà phê",
            ["hp.coffee.line"] = "8 giờ sáng, khách xếp hàng ra tới cửa. Đơn từ quầy, kiosk và điện thoại đều vào chung một hàng chờ.",
            ["hp.coffee.more"] = "Xem MapleCoffee",
            ["hp.nails.trade"] = "Tiệm nail & spa",
            ["hp.nails.line"] = "Thứ Bảy khách walk-in đông, bốn thợ, một thứ tự turn công bằng. Tip và hoa hồng tự cộng khi đóng cửa.",
            ["hp.nails.more"] = "Xem MapleSPA",
            ["hp.garage.trade"] = "Gara",
            ["hp.garage.line"] = "Mỗi chiếc xe là một job. Thợ bấm Bắt đầu, lấy phụ tùng trên kệ, bấm Xong.",
            ["hp.garage.page"] = "Trang đầy đủ sắp ra mắt",
            ["hp.resto.trade"] = "Nhà hàng",
            ["hp.resto.line"] = "Sơ đồ bàn báo cho nhân viên việc tiếp theo, khách gọi món tại bàn bằng ngôn ngữ của họ, phiếu vào thẳng bếp, và AI nhận đặt bàn qua điện thoại.",
            ["hp.resto.more"] = "Xem MaplePOS",
            ["hp.ai.title"] = "AI làm việc thật, bằng ngôn ngữ của khách bạn.",
            ["hp.ai.sub"] = "Không nói suông. Hai việc nó đã làm được.",
            ["hp.ai.coffee.text"] = "Khách gọi món bằng giọng nói ở kiosk MapleCoffee. Đơn hiện lên màn hình, sẵn sàng thanh toán.",
            ["hp.ai.nails.text"] = "Lễ tân AI của MapleSPA nghe điện thoại của tiệm, xem lịch và xác nhận hẹn — kể cả lúc 9 giờ tối.",
            ["hp.co.title"] = "Công ty Canada, không phải tổng đài.",
            ["hp.co.text"] = "Kiosque Érable Inc. xây dựng MapleKiosk tại Longueuil, Québec. Hãy viết cho chúng tôi bằng tiếng Việt, tiếng Anh, tiếng Pháp hoặc tiếng Nga — chính những người làm ra sản phẩm sẽ trả lời.",
            ["hp.co.place"] = "Longueuil, Québec",
            ["hp.co.langs"] = "Tiếng Việt · English · Français · Русский",
            ["hp.co.email"] = "Viết cho chúng tôi",
            ["hp.co.videos"] = "Tất cả video",
            ["hp.end.title"] = "Chọn ngành của bạn, hoặc cứ nói chuyện với chúng tôi.",
            ["hp.end.or"] = "hoặc viết tới",

            // Garage page (/garage)
            ["hp.garage.more"] = "Xem MapleGarage",
            ["gar.meta.title"] = "MapleGarage — Phần mềm cho gara sửa xe độc lập | MapleKiosk",
            ["gar.meta.desc"] = "Đặt lịch, nhận xe có ảnh và chữ ký, báo giá từng hạng mục, bảng theo dõi xe trong xưởng, việc của thợ, phụ tùng và hoá đơn — trên một máy tính bảng. Làm cho gara độc lập.",
            ["gar.hero.title"] = "Từ cuộc gọi đến lúc giao chìa khoá.",
            ["gar.hero.sub"] = "MapleGarage vận hành một gara độc lập trên một máy tính bảng: đặt lịch, nhận xe, báo giá để chủ xe đồng ý hay không, bảng công việc, phụ tùng và hoá đơn.",
            ["gar.hero.watch"] = "Xem video giới thiệu",
            ["gar.hero.note"] = "Mọi hình trên trang này là màn hình thật của MapleGarage. Ứng dụng có tiếng Anh, tiếng Pháp và tiếng Tây Ban Nha.",
            ["gar.watch"] = "Xem đoạn này",
            ["gar.day.title"] = "Một chiếc xe vào xưởng.",
            ["gar.day.sub"] = "Theo một lệnh sửa chữa từ lúc đặt lịch đến lúc giao chìa khoá. Bấm vào màn hình bất kỳ để xem đoạn video đó.",
            ["gar.s.book.t"] = "Đặt lịch vừa sức.",
            ["gar.s.book.d"] = "Lịch hẹn với số xe tối đa mỗi ngày và số cầu nâng do bạn đặt, để không bao giờ nhận nhiều xe hơn khả năng sửa. Khách nhận tin nhắn khi lịch được đặt hoặc dời.",
            ["gar.s.check-in.t"] = "Nhận xe có bằng chứng.",
            ["gar.s.check-in.d"] = "Số đồng hồ, xăng, số móc khoá, các vấn đề khách báo, kiểm tra nhanh có chụp ảnh và chữ ký của khách. Khách nhận biên nhận gửi xe trên điện thoại, ghi rõ không sửa gì khi chưa duyệt báo giá.",
            ["gar.s.quote.t"] = "Báo giá từng hạng mục.",
            ["gar.s.quote.d"] = "Những gì bạn phát hiện trở thành từng hạng mục với phụ tùng, công thợ và thuế, đánh dấu An toàn hoặc Sắp cần. Chủ xe nhận báo giá qua tin nhắn và trả lời có hay không cho từng hạng mục, nên việc thay má phanh không phải chờ cân bằng lốp.",
            ["gar.s.board.t"] = "Mọi chiếc xe, nhìn là thấy.",
            ["gar.s.board.d"] = "Đã nhận, chờ chủ xe, đang sửa, chờ phụ tùng, sẵn sàng giao. Xe quá giờ hẹn được đánh dấu trễ.",
            ["gar.s.my-jobs.t"] = "Việc của tôi.",
            ["gar.s.my-jobs.d"] = "Mỗi thợ thấy việc của mình trên mọi chiếc xe. Bắt đầu, tạm dừng, xong — và phụ tùng lấy trên kệ chỉ với một lần bấm.",
            ["gar.s.parts.t"] = "Phụ tùng, bớt giấy tờ.",
            ["gar.s.parts.d"] = "Xem món nào sắp hết, đưa vào đơn đặt hàng và nhận hàng theo đúng đơn đó. Hàng đặt riêng luôn gắn với chiếc xe cần nó.",
            ["gar.s.bill.t"] = "Hoá đơn khớp báo giá.",
            ["gar.s.bill.d"] = "Hoá đơn được lập từ các hạng mục chủ xe đã duyệt, đúng giá đã báo. Thu tiền mặt bằng một lần bấm cho mỗi tờ tiền, hoặc quẹt thẻ trên máy của bạn.",
            ["gar.s.car-story.t"] = "Lịch sử của từng chiếc xe.",
            ["gar.s.car-story.d"] = "Mỗi lần ghé, số đồng hồ lúc vào và ra, những việc khách từ chối và lần bảo dưỡng tới, đều lưu trên xe. Xe quay lại là có đủ.",
            ["gar.s.tablet.t"] = "Cả xưởng. Một máy tính bảng.",
            ["gar.s.tablet.d"] = "Ô bấm lớn cho quầy và khu sửa xe, mỗi người một mã PIN 6 số. Chủ, cố vấn dịch vụ, thợ, phụ tùng: ai cũng thấy đúng phần việc của mình.",
            ["gar.ai.title"] = "Cuộc gọi lúc 9 giờ tối vẫn có người nghe.",
            ["gar.ai.d"] = "Trợ lý MapleGarage trả lời chat trên web, tin nhắn và điện thoại của bạn. Nó ghi tên, xe và vấn đề, mở yêu cầu sửa chữa cho cố vấn của bạn, và nhắn cho chủ xe đường link để gửi ảnh.",
            ["gar.ai.r1"] = "Nó không bao giờ đoán bệnh hay báo giá. Việc đó là của bạn.",
            ["gar.ai.r2"] = "Nếu xe có vẻ nguy hiểm, nó dặn chủ xe đừng lái và hỏi có cần xe kéo không.",
            ["gar.ai.r3"] = "Nó trả lời bằng ngôn ngữ của khách và xác nhận lại thông tin với khách trước khi lưu.",
            ["gar.more.title"] = "Và còn nữa.",
            ["gar.more.kiosk.t"] = "“Xe tôi tới đâu rồi?”",
            ["gar.more.kiosk.d"] = "Khách nhập số điện thoại ở màn hình quầy để xem xe mình đang ở bước nào.",
            ["gar.more.tv.t"] = "TV phòng chờ",
            ["gar.more.tv.d"] = "Xe trong xưởng, xe sẵn sàng giao và lịch hẹn hôm nay. Chỉ hiện tên, không bao giờ hiện đủ biển số.",
            ["gar.more.follow.t"] = "Chăm sóc sau sửa",
            ["gar.more.follow.d"] = "Gọi lại sau khi giao xe và nhắc bảo dưỡng, tính theo quãng đường xe thực tế chạy.",
            ["gar.more.card.t"] = "Máy quẹt thẻ",
            ["gar.more.card.d"] = "Quẹt thẻ trên máy PAX, hoặc ghi lại khoản thanh toán từ máy bạn đang dùng.",
            ["gar.end.title"] = "Lo sửa xe, không lo giấy tờ.",
