            ["prod.agent.name"] = "Trợ lý giọng nói AI",
            ["prod.agent.for"] = "Nghe điện thoại cho bạn. Bán riêng.",
            ["hp.ai.more"] = "Xem trợ lý giọng nói AI, bán riêng",
            ["ag.meta.title"] = "Trợ lý giọng nói AI: nghe mọi cuộc gọi, ngày lẫn đêm | MapleKiosk",
            ["ag.meta.desc"] = "Trợ lý giọng nói AI cho điện thoại của tiệm: đặt lịch hẹn, nhận đơn mang đi và đặt bàn, trả lời giờ mở cửa, giá và chỗ đậu xe, bằng đúng ngôn ngữ của khách. Bán riêng.",
            ["ag.product"] = "Trợ lý giọng nói AI MapleKiosk",
            ["ag.hero.title"] = "Không bỏ lỡ cuộc gọi nào.",
            ["ag.hero.sub"] = "Trợ lý giọng nói AI nhấc máy khi tay bạn đang bận, ngày lẫn đêm, với giọng nói tự nhiên, thân thiện. Khách nói tiếng gì, nó trả lời bằng tiếng đó. Nó đặt lịch hẹn, nhận đơn mang đi và trả lời những câu hỏi bạn nghe mỗi ngày.",
            ["ag.hero.watch"] = "Xem phim (tiếng Anh)",
            ["ag.hero.alone"] = "Bán riêng: không cần sản phẩm MapleKiosk nào khác. Đang dùng hệ thống của chúng tôi? Trợ lý đã có sẵn bên trong.",
            ["ag.watch"] = "Xem đoạn này",
            ["ag.why.title"] = "Tay bạn đang bận. Điện thoại vẫn reo.",
            ["ag.why.d"] = "Đang làm móng, đang pha espresso hay đang bưng món giờ cao điểm: cuộc gọi vào hộp thư thoại, và khách gọi tiệm khác.",
            ["ag.why.alt"] = "Thông báo trên điện thoại: bốn cuộc gọi nhỡ, đều vào hộp thư thoại.",
            ["ag.does.title"] = "Nó làm gì trong cuộc gọi",
            ["ag.does.sub"] = "Mỗi hình đều lấy từ phim. Bấm vào để xem đoạn đó.",
            ["ag.s.book.t"] = "Đặt lịch hẹn",
            ["ag.s.book.d"] = "Với tiệm nail, nó đặt, dời và xác nhận lịch hẹn ngay vào lịch của bạn, rồi nhắn tin cho khách.",
            ["ag.s.book.alt"] = "Cuộc gọi tới Maple Nails: khách hỏi làm gel thứ Bảy khoảng 2 giờ; trợ lý đặt 2 giờ chiều với Linda và gửi tin nhắn.",
            ["ag.s.order.t"] = "Nhận đơn",
            ["ag.s.order.d"] = "Với quán cà phê và nhà hàng, nó nhận đơn mang đi, đặt bàn và trả lời câu hỏi về thực đơn.",
            ["ag.s.order.alt"] = "Cuộc gọi tới Café Maple: hai latte và một croissant mang đi thành đơn #1042, xong sau mười phút.",
            ["ag.s.questions.t"] = "Trả lời câu hỏi hằng ngày",
            ["ag.s.questions.d"] = "Giờ mở cửa, giá, địa chỉ và chỗ đậu xe: những câu mọi doanh nghiệp nghe suốt ngày.",
            ["ag.s.questions.alt"] = "Hỏi và đáp: giờ mở cửa, giá, địa chỉ và chỗ đậu xe.",
            ["ag.s.team.t"] = "Biết khi nào chuyển máy",
            ["ag.s.team.d"] = "Nó nghe nhiều cuộc gọi cùng lúc và trả lời bằng ngôn ngữ của người gọi, dù là tiếng gì. Nó nhắn tin xác nhận và chuyển cho nhân viên khi cần người thật.",
            ["ag.s.team.alt"] = "Bốn điểm: nhiều cuộc gọi cùng lúc, tiếng Anh và tiếng Pháp, tin nhắn xác nhận, chuyển cho nhân viên.",
            ["ag.own.title"] = "Mua riêng cũng được.",
            ["ag.own.d"] = "Trợ lý nghe điện thoại của bạn dù quầy đang dùng hệ thống nào. Hợp với tiệm nail, quán cà phê, nhà hàng, gara, và mọi doanh nghiệp hay lỡ cuộc gọi.",
            ["ag.own.r1"] = "Không cần máy tính tiền, máy tính bảng hay kiosk MapleKiosk.",
            ["ag.own.r2"] = "Đang dùng MapleCoffee, MapleSPA, MaplePOS hay MapleGarage? Trợ lý đã có sẵn: lịch hẹn và đơn hàng vào thẳng hệ thống của bạn.",
            ["ag.own.r3"] = "Bắt đầu với trợ lý hôm nay. Thêm phần còn lại của hệ thống sau, nếu bạn muốn.",
            ["ag.in.title"] = "Đã có trong mọi hệ thống MapleKiosk",
            ["ag.in.sub"] = "Nếu bạn dùng một hệ thống của chúng tôi, trợ lý chạy ngay bên trong.",
            ["ag.in.coffee"] = "Nhận đơn mang đi qua điện thoại và gửi tới quầy tính tiền.",
            ["ag.in.nails"] = "Đặt lịch vào sổ hẹn của tiệm, đúng thợ.",
            ["ag.in.resto"] = "Nhận đặt bàn và đơn mang đi.",
            ["ag.in.garage"] = "Ghi tên, xe và vấn đề, rồi mở yêu cầu sửa xe.",
            ["ag.end.title"] = "Không bao giờ lỡ cuộc gọi nữa.",

            // MapleSPA pricing (/nails/pricing)
            ["spa.cta.pricing"] = "Xem bảng giá",
