            ["onb.welcome"] = "Chào mừng {0} đã đồng hành cùng MapleKiosk!",
            ["onb.intro"] = "Bảng khảo sát ngắn này là nền tảng để chúng tôi xây dựng hệ thống cho bạn. Mọi thông tin bạn cung cấp — dịch vụ, giờ mở cửa, nhân viên và phong cách — đều được đưa thẳng vào hệ thống, nên trả lời càng đầy đủ thì kết quả càng phù hợp với cửa hàng. Làm theo thứ tự nào cũng được; câu trả lời được lưu tự động và bạn có thể quay lại bất cứ lúc nào.",
