            ["onb.f.logo.replace"] = "Thay logo",
            ["onb.f.logo.hint"] = "Chất lượng tốt nhất bạn có — SVG, PNG nền trong suốt hoặc file của designer. Ảnh chụp bảng hiệu cũng được.",

            // Restaurant page (MaplePOS)
            ["rp.meta.title"] = "MaplePOS — phần mềm POS cho nhà hàng phục vụ tại bàn | MapleKiosk",
            ["rp.meta.desc"] = "Sơ đồ bàn báo cho nhân viên việc cần làm tiếp, gọi món bằng QR tại bàn theo ngôn ngữ của khách, màn hình bếp, AI nhận đặt bàn qua điện thoại và tin nhắn, thanh toán và tip trong vài giây. Sản xuất tại Québec.",
            ["rp.hero.title"] = "Điều hành sàn, không phải hỗn loạn.",
            ["rp.hero.sub"] = "MaplePOS là phần mềm bán hàng cho nhà hàng phục vụ tại bàn. Nó báo cho nhân viên việc cần làm tiếp, chuyển mọi món vào bếp, nhận đặt bàn cả khi bạn ngủ và thanh toán chỉ trong vài giây.",
            ["rp.hero.watch"] = "Xem phim",
            ["rp.hero.note"] = "Mọi màn hình trong các phim này đều có sẵn trong ứng dụng.",
            ["rp.hero.alt"] = "Sơ đồ bàn MaplePOS: mỗi bàn với trạng thái, số khách, thời gian và danh sách việc tiếp theo",
            ["rp.watch"] = "Xem",
            ["rp.lang"] = "Phim bằng",
            ["rp.night.title"] = "Một tối ở nhà hàng",
            ["rp.night.sub"] = "Theo chân một ca phục vụ từ lượt đặt bàn đầu tiên đến khoản tip cuối cùng. Mỗi bước là một phim dài một phút.",
            ["rp.s.book.t"] = "Kín lịch, không bao giờ trùng bàn",
            ["rp.s.book.d"] = "Lượt đặt bàn hiện trên sổ trong ngày — bàn theo cột, giờ theo hàng — nên không bàn nào bị bán hai lần. Khách đến được đưa vào sảnh chờ, khách vãng lai được báo thời gian chờ và xếp bàn chỉ với vài thao tác.",
            ["rp.s.book.alt"] = "Sổ đặt bàn trong ngày: bàn theo cột, giờ theo hàng",
            ["rp.s.phone.t"] = "Nhận đặt bàn cả khi bạn ngủ",
            ["rp.s.phone.d"] = "Trợ lý AI nghe điện thoại và đặt vào những bàn thật sự còn trống. Khách cũng có thể nhắn tin để đặt — bằng ngôn ngữ của họ — hoặc đặt online. Cuộc gọi nào AI không xử lý được sẽ chuyển lại cho nhân viên gọi lại.",
            ["rp.s.phone.alt"] = "Trợ lý AI đang nghe gọi bên cạnh sổ đặt bàn",
            ["rp.s.floor.t"] = "Luôn biết việc cần làm tiếp",
            ["rp.s.floor.d"] = "Sơ đồ bàn hiển thị mọi bàn — trống, đang chờ mình, đang dùng bữa, sắp về — kèm số khách và thời gian. Mục “Tiếp theo” báo cho nhân viên việc quan trọng lúc này: bưng món, trả lời khách, nhận order, mời thanh toán.",
