            ["spa.s.walkins.t"] = "Клиенты без записи и группы — без хаоса",
            ["spa.s.walkins.d"] = "Пришли четыре подруги сразу? MapleSPA отдаёт каждую следующему свободному мастеру по очереди и запускает всех вместе. Записанные клиенты и клиенты без записи — на одной доске, поэтому всегда видно, кто свободен.",
            ["spa.s.walkins.alt"] = "Группа клиентов без записи ждёт в салоне",
            ["spa.s.checkout.t"] = "Расчёт за секунды",
            ["spa.s.checkout.d"] = "В чеке уже есть услуги и мастер. Клиент выбирает чаевые на экране и платит картой, наличными или подарочной картой. Без калькулятора и без очереди у кассы.",
            ["spa.s.checkout.alt"] = "Заставка: расчёт за секунды",
            ["spa.s.payday.t"] = "Зарплата за минуты, а не за ночь",
            ["spa.s.payday.d"] = "Процент и чаевые каждого мастера считаются с каждого чека, поэтому к концу недели зарплата готова. Каждый мастер видит свой заработок у себя в телефоне.",
            ["spa.s.payday.alt"] = "Заработок мастера за неделю на телефоне",
            ["spa.s.promos.t"] = "Видно, какая акция приводит клиентов",
            ["spa.s.promos.d"] = "Запустите акцию и поделитесь ею в Facebook, Instagram или ссылкой. MapleSPA показывает, сколько людей перешли, сколько записались и на какую сумму.",
            ["spa.s.promos.alt"] = "Результаты акции: переходы, записи и сумма по каждому источнику",
            ["spa.s.photo.t"] = "Клиент присылает фото и сразу получает совет",
            ["spa.s.photo.d"] = "Клиент присылает фото своих ногтей в сообщении. ИИ сразу отвечает: даёт совет и подбирает подходящую услугу, а клиент может тут же записаться.",
            ["spa.s.photo.alt"] = "Переписка с клиентом на телефоне",
            ["spa.end.title"] = "Посмотрите, как MapleSPA работает в вашем салоне.",
            ["spa.cta.trial"] = "Тест-драйв",
            // MapleCoffee (/coffee) page
            ["cof.meta.title"] = "MapleCoffee — POS для кофеен, бабл-ти и фастфуда | MapleKiosk",
            ["cof.hero.title"] = "Вся кофейня на одном экране.",
            ["cof.hero.sub"] = "MapleCoffee берёт на себя ежедневную работу за стойкой: утренний наплыв, заказы через киоск и онлайн, расчёт и чаевые, постоянных гостей и подарочные карты, раздел чаевых и меню. Персонал может работать на русском, английском, французском или вьетнамском.",
            ["cof.hero.watch"] = "Смотреть фильм",
            ["cof.hero.note"] = "Каждый экран в этих фильмах уже есть в приложении. Фильмы на английском.",
            ["cof.hero.alt"] = "Киоск заказов MapleCoffee в кофейне",
            ["cof.watch"] = "Смотреть",
            ["cof.day.title"] = "Что MapleCoffee берёт на себя",
            ["cof.day.sub"] = "Семь ежедневных задач кофейни и как MapleCoffee их решает. О каждой — фильм на одну минуту.",
            ["cof.s.rush.t"] = "Утренний наплыв: тот напиток, то имя",
            ["cof.s.rush.d"] = "Каждый заказ приходит на бар с напитком, пожеланиями и именем гостя. Бариста готовят по порядку и называют правильное имя, даже когда очередь стоит до двери.",
            ["cof.s.rush.alt"] = "Бариста Алвин перед утренней очередью",
            ["cof.s.kiosk.t"] = "Вторая касса, которая никогда не отдыхает",
            ["cof.s.kiosk.d"] = "Гости заказывают в киоске или заранее с телефона. Нажимают Order Now, выбирают напитки, сами проверяют заказ — и он сразу уходит на бар. Персонал продолжает готовить, а очередь движется.",
            ["cof.s.kiosk.alt"] = "Киоск заказов с кнопкой Order Now",
            ["cof.s.voice.t"] = "Гость просто говорит заказ на своём языке",
            ["cof.s.voice.d"] = "У голосового киоска гость просто говорит, что хочет, — по-английски, по-французски или на своём языке. Заказ появляется на экране, пока он говорит, и гость его подтверждает.",
            ["cof.s.voice.alt"] = "Гость заказывает по-французски у голосового киоска",
            ["cof.s.checkout.t"] = "Быстрый расчёт, чаевые без неловкости",
            ["cof.s.checkout.d"] = "Гость выбирает чаевые на своём экране, затем прикладывает или вставляет карту. Никому не нужно разворачивать экран и ждать, и очередь не стоит.",
            ["cof.s.checkout.alt"] = "Заставка: расчёт проще",
            ["cof.s.loyalty.t"] = "Новые гости становятся постоянными",
            ["cof.s.loyalty.d"] = "Гости копят баллы и получают награды, например скидку $2, прямо на кассе. Подарочные карты продаются и принимаются на том же экране.",
            ["cof.s.loyalty.alt"] = "Экран кассы применяет приветственную скидку $2",
            ["cof.s.tips.t"] = "Честный раздел чаевых, зарплата за минуты",
            ["cof.s.tips.d"] = "Выберите, как делить чаевые: поровну между всеми на смене, официанту целиком или долю официанту, а остальное в общий котёл. MapleCoffee считает по каждому заказу, поэтому зарплата готова за минуты.",
            ["cof.s.tips.alt"] = "Настройки чаевых: общий котёл, официанту или доля официанту",
            ["cof.s.tips.howto"] = "Как настроить раздел чаевых",
            ["cof.s.menu.t"] = "Измените цену один раз — она верна везде",
            ["cof.s.menu.d"] = "Измените цену или позицию один раз. Касса, киоск и онлайн-заказ сразу показывают изменение, и никто не платит по старой цене.",
            ["cof.s.menu.alt"] = "Заставка: измените один раз",
            ["cof.end.title"] = "Посмотрите, как MapleCoffee работает в вашей кофейне.",
            ["cof.cta.trial"] = "Тест-драйв",

