            // Garage page (/garage)
            ["hp.garage.more"] = "Смотреть MapleGarage",
            ["gar.meta.title"] = "MapleGarage — программа для независимых автосервисов | MapleKiosk",
            ["gar.meta.desc"] = "Запись, приёмка с фото и подписью, смета по каждой работе, доска машин в цеху, задания механиков, запчасти и счёт — на одном планшете. Для независимых автосервисов.",
            ["gar.hero.title"] = "От звонка до возврата ключей.",
            ["gar.hero.sub"] = "MapleGarage ведёт независимый автосервис на одном планшете: запись, приёмку, смету, по которой владелец говорит «да» или «нет», доску работ, запчасти и счёт.",
            ["gar.hero.watch"] = "Смотреть обзор",
            ["gar.hero.note"] = "Каждая картинка на этой странице — настоящий экран MapleGarage. Приложение работает на английском, французском и испанском.",
            ["gar.watch"] = "Смотреть этот момент",
            ["gar.day.title"] = "Машина заезжает.",
            ["gar.day.sub"] = "Проследите один заказ-наряд от записи до ключей. Нажмите на любой экран, чтобы посмотреть этот момент обзора.",
            ["gar.s.book.t"] = "Запись без перегруза.",
            ["gar.s.book.d"] = "Календарь с лимитом машин в день и числом подъёмников, которые задаёте вы, — чтобы не обещать больше, чем успеете. Клиент получает SMS, когда запись создана или перенесена.",
            ["gar.s.check-in.t"] = "Приёмка с доказательствами.",
            ["gar.s.check-in.d"] = "Пробег, топливо, номер ключа, жалобы владельца, быстрый осмотр с фото и его подпись. Квитанция о сдаче приходит ему на телефон, и в ней сказано: без одобренной сметы работы не начинаются.",
            ["gar.s.quote.t"] = "Смета по каждой работе.",
            ["gar.s.quote.d"] = "Всё найденное становится работами с запчастями, часами и налогом, с пометкой «Безопасность» или «Скоро». Владелец получает смету по SMS и говорит «да» или «нет» по каждой работе — тормоза не ждут балансировки.",
            ["gar.s.board.t"] = "Все машины — одним взглядом.",
            ["gar.s.board.d"] = "Принята, ждёт владельца, в ремонте, ждёт запчастей, готова к выдаче. Машина, не успевшая к обещанному времени, помечается как опаздывающая.",
            ["gar.s.my-jobs.t"] = "Мои работы.",
            ["gar.s.my-jobs.d"] = "Каждый механик видит свои работы по всем машинам. Старт, пауза, готово — и запчасть берётся с полки одним нажатием.",
            ["gar.s.parts.t"] = "Запчасти без бумажек.",
            ["gar.s.parts.d"] = "Видно, что заканчивается: добавьте в заказ и примите по этому заказу. Спецзаказ остаётся привязан к своей машине.",
            ["gar.s.bill.t"] = "Счёт совпадает со сметой.",
            ["gar.s.bill.d"] = "Счёт собирается из одобренных владельцем работ по цене сметы. Наличные — одним нажатием на купюру, карта — на вашем терминале.",
            ["gar.s.car-story.t"] = "История каждой машины.",
            ["gar.s.car-story.d"] = "Каждый визит, пробег при приёмке и выдаче, отклонённые работы и срок следующего ТО сохраняются в карточке машины. Когда она вернётся, всё уже там.",
            ["gar.s.tablet.t"] = "Весь сервис. Один планшет.",
            ["gar.s.tablet.d"] = "Крупные плитки для стойки и цеха и шестизначный PIN у каждого. Владелец, мастер-приёмщик, механик, кладовщик: каждый видит то, что нужно для его работы.",
            ["gar.ai.title"] = "Звонок в 9 вечера не останется без ответа.",
            ["gar.ai.d"] = "Ассистент MapleGarage отвечает в веб-чате, по SMS и по телефону. Он записывает имя, машину и проблему, открывает заявку на ремонт для вашего мастера и отправляет владельцу ссылку для фото.",
            ["gar.ai.r1"] = "Он никогда не угадывает диагноз или цену. Это остаётся за вами.",
            ["gar.ai.r2"] = "Если машина звучит опасно, он просит владельца не ездить на ней и спрашивает, нужен ли эвакуатор.",
            ["gar.ai.r3"] = "Он отвечает на языке клиента и сверяет с ним детали, прежде чем что-то сохранить.",
            ["gar.more.title"] = "А ещё.",
            ["gar.more.kiosk.t"] = "«Где моя машина?»",
            ["gar.more.kiosk.d"] = "Клиент вводит номер телефона на экране у стойки и видит, на каком этапе его машина.",
            ["gar.more.tv.t"] = "Телевизор в зале ожидания",
            ["gar.more.tv.d"] = "Машины в цеху, готовые к выдаче и записи на сегодня. Только имя, никогда полный номер.",
            ["gar.more.follow.t"] = "Напоминания",
            ["gar.more.follow.d"] = "Звонки после выдачи и напоминания о ТО, рассчитанные по реальному пробегу машины.",
            ["gar.more.card.t"] = "Платёжный терминал",
