            ["ag.meta.desc"] = "Голосовой ИИ-агент для телефона вашего бизнеса: записывает клиентов, принимает заказы навынос и брони, отвечает про часы работы, цены и парковку, на языке вашего клиента. Продаётся отдельно.",
            ["ag.product"] = "Голосовой ИИ-агент MapleKiosk",
