            ["ag.s.book.t"] = "Записывает на приём",
            ["ag.s.book.d"] = "Для салонов он записывает, переносит и подтверждает визиты прямо в ваш календарь и отправляет клиенту SMS.",
            ["ag.s.book.alt"] = "Звонок в Maple Nails: клиентка просит гель-маникюр в субботу около двух; агент записывает на 14:00 к Линде и отправляет SMS.",
            ["ag.s.order.t"] = "Принимает заказ",
