            ["ag.s.questions.alt"] = "Вопросы и ответы: часы работы, цена, адрес и парковка.",
            ["ag.s.team.t"] = "Знает, когда передать трубку",
            ["ag.s.team.d"] = "Он отвечает на несколько звонков сразу, на языке звонящего, каким бы он ни был. Присылает подтверждения по SMS и переключает на сотрудника, когда нужен человек.",
            ["ag.s.team.alt"] = "Четыре пункта: несколько звонков сразу, английский и французский, подтверждения по SMS, передача команде.",
            ["ag.own.title"] = "Можно купить отдельно.",
