            ["rp.s.book.alt"] = "Дневная книга: столики по горизонтали, время по вертикали",
            ["rp.s.phone.t"] = "Бронируйте столики, пока спите",
            ["rp.s.phone.d"] = "ИИ-ассистент отвечает на звонки и бронирует только реально свободные столики. Гости также могут забронировать по SMS — на своём языке — или онлайн. Звонок, с которым он не справился, возвращается персоналу как обратный звонок.",
