            ["rp.s.qr.t"] = "Каждый столик заказывает на своём языке",
            ["rp.s.qr.d"] = "Гости сканируют QR-код на столике и заказывают с телефона на английском, французском, испанском или вьетнамском. На кухню ничего не уходит, пока они не нажмут «Отправить», — а когда просят счёт, зал сразу это видит.",
            ["rp.s.qr.alt"] = "QR-меню столика на телефоне гостя",
